const { cookies, intern_id, start_date, end_date, sumstatus } = $json;

// ---------- Setup ----------
if (cookies && cookies.length) {
    await $page.setCookie(...cookies);
}
await $page.setViewport({ width: 1512, height: 982, deviceScaleFactor: 1 });
await $page.goto('https://meta-digitrading.lhike-erp.com/totaladspent', {
    waitUntil: 'networkidle2',
    timeout: 60000
});

async function waitForLoadingToClear() {
    // FIX: check computed style, not just inline style, so it also clears
    // when #bgloading is hidden via a CSS class rather than el.style.display.
    await $page.waitForFunction(() => {
        const el = document.querySelector('#bgloading');
        if (!el) return true;
        return window.getComputedStyle(el).display === 'none';
    }, { timeout: 60000 });
    await new Promise(resolve => setTimeout(resolve, 1500));
}
await waitForLoadingToClear();

// ---------- Helper: set a bootstrap-select dropdown ----------
async function setBootstrapSelect(selectId, value) {
    await $page.waitForSelector(`#${selectId}`, { timeout: 15000 });
    await $page.select(`#${selectId}`, String(value));
    await $page.evaluate((id) => {
        const el = document.getElementById(id);
        el.dispatchEvent(new Event('change', { bubbles: true }));
        if (window.jQuery) {
            window.jQuery(el).trigger('change');
            if (window.jQuery(el).selectpicker) {
                window.jQuery(el).selectpicker('refresh');
            }
        }
    }, selectId);
}

// ---------- Filter By (sumstatus) ----------
if (sumstatus !== undefined && sumstatus !== null && sumstatus !== '') {
    await setBootstrapSelect('sumstatus', sumstatus);
}

// ---------- Filter by Intern ----------
if (intern_id !== undefined && intern_id !== null && intern_id !== '') {
    await setBootstrapSelect('internid', intern_id);
}

// ---------- Filter by Date Range ----------
function parseDate(d) {
    const [y, m, day] = d.split('-').map(Number);
    return { year: y, month: m, day };
}
const startDate = parseDate(start_date);
const endDate = parseDate(end_date);

await $page.waitForSelector('#conversion-report-range', {
    visible: true,
    timeout: 15000
});
await $page.click('#conversion-report-range');
await $page.waitForSelector('.daterangepicker', {
    visible: true,
    timeout: 15000
});

function monthNameToNumber(name) {
    const months = [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
    ];
    return months.indexOf(name) + 1;
}

// Returns the text of each visible calendar panel header, e.g. ["July 2026", "August 2026"]
async function getVisibleMonths() {
    return await $page.evaluate(() =>
        Array.from(document.querySelectorAll('.daterangepicker .calendar .month'))
            .map(el => el.textContent.trim())
    );
}

async function clickDayOnSide(side, day) {
    const cells = await $page.$$(
        `.daterangepicker .calendar.${side} .calendar-table td.available:not(.off)`
    );
    for (const cell of cells) {
        const text = await $page.evaluate(el => el.textContent.trim(), cell);
        if (parseInt(text, 10) === day) {
            await cell.click();
            return true;
        }
    }
    return false;
}

// FIX: unified date selector.
// The left/right panels are linked consecutive months, so the target month can
// appear on EITHER panel (and for same-month ranges, both start & end land on the
// same panel). This finds whichever visible panel shows the target month and clicks
// there, navigating both panels together only when the month isn't currently visible.
async function selectDate(targetYear, targetMonth, day) {
    for (let attempts = 0; attempts < 36; attempts++) {
        const months = await getVisibleMonths(); // [leftText, rightText]

        for (let i = 0; i < months.length; i++) {
            const [name, yearStr] = months[i].split(' ');
            if (monthNameToNumber(name) === targetMonth &&
                parseInt(yearStr, 10) === targetYear) {
                const side = i === 0 ? 'left' : 'right';
                return await clickDayOnSide(side, day);
            }
        }

        // Not visible yet — navigate toward the target based on the left panel.
        const [leftName, leftYearStr] = months[0].split(' ');
        const currentMonth = monthNameToNumber(leftName);
        const currentYear = parseInt(leftYearStr, 10);
        const diff = (targetYear - currentYear) * 12 + (targetMonth - currentMonth);

        const btn = await $page.$(
            diff > 0
                ? '.daterangepicker .next.available'
                : '.daterangepicker .prev.available'
        );
        if (!btn) return false;

        await btn.click();
        await new Promise(resolve => setTimeout(resolve, 300));
    }
    return false;
}

// Select Start Date, then End Date (order matters: daterangepicker expects start first)
await selectDate(startDate.year, startDate.month, startDate.day);
await new Promise(resolve => setTimeout(resolve, 300));

await selectDate(endDate.year, endDate.month, endDate.day);
await new Promise(resolve => setTimeout(resolve, 300));

// Apply Date Range
await $page.click('.daterangepicker .applyBtn');
await new Promise(resolve => setTimeout(resolve, 500));

// ---------- Submit Filters ----------
await $page.waitForSelector('.search-ads', {
    visible: true,
    timeout: 15000
});
await $page.click('.search-ads');
await waitForLoadingToClear();

// ---------- Verify Applied Filters ----------
const appliedStart = await $page
    .$eval('#txtdstart', el => el.value)
    .catch(() => null);
const appliedEnd = await $page
    .$eval('#txtdend', el => el.value)
    .catch(() => null);
const appliedIntern = await $page
    .$eval('#internid', el =>
        el.options[el.selectedIndex]
            ? el.options[el.selectedIndex].textContent.trim()
            : null
    )
    .catch(() => null);
const appliedSumstatus = await $page
    .$eval('#sumstatus', el =>
        el.options[el.selectedIndex]
            ? el.options[el.selectedIndex].textContent.trim()
            : null
    )
    .catch(() => null);

// ---------- Extract All Data Rows + Total/Average Rows ----------
const tableData = await $page.evaluate(() => {
    const rows = Array.from(
        document.querySelectorAll('.roastable table.tg tbody tr')
    );

    const dataRows = [];
    let totalRow = null;
    let averageRow = null;

    rows.forEach(row => {
        const cells = Array.from(row.querySelectorAll('td')).map(td =>
            td.textContent.trim().replace(/\s+/g, ' ')
        );

        if (!cells.length) return;

        // retview cells are, in order: [Returned AMT, Returned, RTS Rate]
        const retCells = Array.from(row.querySelectorAll('td.retview'))
            .map(td => td.textContent.trim().replace(/\s+/g, ' '));

        // delview cells are, in order: [Delivered AMT, Delivered]
        const delCells = Array.from(row.querySelectorAll('td.delview'))
            .map(td => td.textContent.trim().replace(/\s+/g, ' '));

        // Daily rows
        if (/^\d{4}-\d{2}-\d{2}$/.test(cells[0])) {
            dataRows.push({
                date: cells[0],
                orders: cells[1],
                sales: cells[2],
                ad_spent: cells[3],
                roas: cells[4],
                returned_amt: retCells[0] || null,
                returned: retCells[1] || null,
                rts_rate: retCells[2] || null,
                delivered_amt: delCells[0] || null,
                delivered: delCells[1] || null
            });
            return;
        }

        // Total row (label cell, e.g. "TOTAL AMOUNT")
        if (/^TOTAL/i.test(cells[0])) {
            totalRow = {
                label: cells[0],
                orders: cells[1],
                sales: cells[2],
                ad_spent: cells[3],
                roas: cells[4],
                returned_amt: retCells[0] || null,
                returned: retCells[1] || null,
                rts_rate: retCells[2] || null,
                delivered_amt: delCells[0] || null,
                delivered: delCells[1] || null
            };
            return;
        }

        // Average row
        if (/^AVERAGE/i.test(cells[0])) {
            averageRow = {
                label: cells[0],
                orders: cells[1],
                sales: cells[2],
                ad_spent: cells[3],
                roas: cells[4],
                returned_amt: retCells[0] || null,
                returned: retCells[1] || null,
                rts_rate: retCells[2] || null,
                delivered_amt: delCells[0] || null,
                delivered: delCells[1] || null
            };
        }
    });

    return {
        rows: dataRows,
        total: totalRow,
        average: averageRow
    };
});

// Optional Label
const dateLabel = `${start_date}_${end_date}`;

// ---------- Return ----------
return [
    {
        json: {
            intern_id,
            start_date,
            end_date,
            dateLabel,
            sumstatus,
            appliedStart,
            appliedEnd,
            appliedIntern,
            appliedSumstatus,
            totalRows: tableData.rows.length,
            rows: tableData.rows,
            total: tableData.total,
            average: tableData.average,
            status: "success"
        }
    }
];

