// --- 1. Grab both items from the previous node ---
const items = $input.all();

const workspace_id = $('Webhook').first().json.body.workspace_id;
const api_key = $('Webhook').first().json.body.api_key;
const intern_id = $('Webhook').first().json.body.intern_id;
const webhook_url = $('Webhook').first().json.body.webhook_url;

// Main object with rows = the item that has a "rows" array
const mainItem = items.find(i => Array.isArray(i.json.rows));
// Extra object = the item WITHOUT rows (the flat metrics object)
const extraItem = items.find(i => !Array.isArray(i.json.rows));

const main = mainItem.json;

// --- 2. Pull out the date + fields to append (everything except "date") ---
const { date: targetDate, ...extraFields } = extraItem.json;

// --- 3. Merge into the matching row by date ---
const mergedRows = main.rows.map(row => {
    if (row.date === targetDate) {
        return { ...row, ...extraFields };
    }
    return row;
});

// --- 4. Keep past + today's rows only; drop future placeholders ---
// FIX: compute "today" in the business timezone (Asia/Manila), not server/UTC time,
// so today's row isn't mistaken for a future date.
function getTodayInTZ(timeZone) {
    const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
    }).formatToParts(new Date());

    const y = parts.find(p => p.type === 'year').value;
    const m = parts.find(p => p.type === 'month').value;
    const d = parts.find(p => p.type === 'day').value;

    const d2 = new Date(`${y}-${m}-${d}T00:00:00`);
    d2.setHours(0, 0, 0, 0);
    return d2;
}

const today = getTodayInTZ('Asia/Manila');

const rowsToSend = mergedRows.filter(row => {
    const rowDate = new Date(row.date);
    rowDate.setHours(0, 0, 0, 0);

    // FIX: today is always kept, same as past dates — even if values are
    // still 0 because the day isn't over yet. Only strictly future dates
    // (placeholders beyond today) get dropped.
    return rowDate <= today;
});

// --- 5. Return the updated object ---
return [
    {
        json: {
            ...main,
            webhook_url,
            workspace_id,
            api_key,
            rows_count: rowsToSend.length,
            rows: rowsToSend
        }
    }
];

