const { cookies, intern_id, start_date, end_date } = $json;
if (cookies && cookies.length) {
    await $page.setCookie(...cookies);
}
await $page.setViewport({
    width: 1512,
    height: 982,
    deviceScaleFactor: 1
});
await $page.goto(
    `https://meta-digitrading.lhike-erp.com/dashboard?stat=1&interns=${intern_id}&date_field=ord_date&start=${start_date}&end=${end_date}`,
    {
        waitUntil: 'networkidle2',
        timeout: 60000
    }
);
const landedUrl = $page.url();
const stats = await $page.evaluate(() => {
    function parseCard(card) {
        if (!card) return null;
        const amountText =
            card.querySelector('.number span')?.textContent?.trim() || null;
        const descEl = card.querySelector('.desc');
        const amount = amountText
            ? parseFloat(amountText.replace(/[^0-9.]/g, ''))
            : null;
        const percentText =
            descEl?.querySelector('b')?.textContent?.trim() || null;
        const descFullText =
            descEl?.textContent?.replace(/\s+/g, ' ').trim() || null;
        const countMatch = descFullText?.match(/\((\d+)\)/);
        const count = countMatch
            ? parseInt(countMatch[1], 10)
            : null;
        const percent = percentText
            ? parseFloat(percentText.replace(/[^0-9.]/g, ''))
            : null;
        return {
            raw: amountText,
            amount,
            label: descFullText,
            count,
            percent
        };
    }

    const salesCard = document.querySelector('#div-list-sales');
    const rtsCard = document
        .querySelector('.dashboard-stat.red-thunderbird')
        ?.closest('.col-lg-4, .col-md-4, .col-sm-6, .col-xs-12');
    const deliveredCard = document.querySelector('.dashboard-stat.purple');
    const returnedCard = document.querySelector('.dashboard-stat.red-flamingo');
    const forReturnCard = [...document.querySelectorAll('.dashboard-stat')]
        .find(el => /FOR RETURN/i.test(el.querySelector('.desc')?.textContent || ''));

    return {
        totalSales: parseCard(salesCard),
        totalRts: parseCard(rtsCard),
        totalDelivered: parseCard(deliveredCard),
        totalReturned: parseCard(returnedCard),
        totalForReturn: parseCard(forReturnCard)
    };
});
return [
    {
        json: {
            intern_id,
            start_date,
            end_date,
            landedUrl,
            ...stats
        }
    }
];

