// --- Helper: turn "158,607.00" / "14.98%" / "" into a real number ---
function toNumber(val) {
    if (val === null || val === undefined || val === '') return 0;
    const cleaned = String(val).replace(/,/g, '').replace(/%/g, '').trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
}

// Fields that should be converted from formatted strings to plain numbers
const numericFields = [
    'orders',
    'sales',
    'ad_spent',
    'roas',
    'returned_amt',
    'returned',
    'rts_rate',
    'delivered_amt',
    'delivered'
];

function normalizeRow(row) {
    const out = { ...row };
    for (const field of numericFields) {
        if (field in out) {
            out[field] = toNumber(out[field]);
        }
    }
    return out;
}

// --- 1. Grab both items from the previous node ---
const items = $input.all();
// Main object with rows = the item that has a "rows" array
const mainItem = items.find(i => Array.isArray(i.json.rows));
// Total object = the item that has a "total" object
const totalItem = items.find(i => i.json.total);
const main = mainItem.json;

// --- 2. Pull out the date + total values to append ---
const targetDate = totalItem?.json.date;
const total = totalItem?.json.total || {};

// --- 3. Merge total into the matching row by date, then normalize numbers ---
const mergedRows = main.rows.map(row => {
    const merged = row.date === targetDate ? { ...row, ...total } : row;
    return normalizeRow(merged);
});

const intern_id = $input.first().json.intern_id;
const rows_count = $input.first().json.rows.length;

// --- 4. Return the updated object ---
return [
    {
        json: {
            intern_id,
            rows_count,
            rows: mergedRows
        }
    }
];

const data = $input.all().map(item => item.json);

// Merge all objects into one
